// Escribe el resumen del día con el estilo de la persona
const d = $input.first().json.b || {};
if (d.existe && d.texto) return [{ json: { nuevo: false, texto: d.texto } }];
if (!d.clave) return [{ json: { nuevo: false, texto: null } }];

const p = d.perfil || {};
const dia = d.dia || {};
const eventos = (dia.eventos || []).map((e) => `- ${e.hora} a ${e.hora_fin}: ${e.titulo} (${e.categoria}${e.prioridad === 1 ? ', importante' : ''})`);
const vencen = (dia.tareas_que_vencen || []).map((t) => '- ' + t.texto);
const pendientes = (d.pendientes || []).slice(0, 6).map((t) => '- ' + t.texto);
const libres = (dia.espacios_libres || []).map((h) => `${h.desde}-${h.hasta}`);

const estilo = [];
if ((p.mensajes_vistos || 0) >= 2) {
  estilo.push(p.formalidad > 0.65 ? 'trato de usted' : p.formalidad < 0.35 ? 'muy coloquial y cercano' : 'cercano, tuteando');
  estilo.push(p.emojis > 0.4 ? 'con un par de emojis' : 'sin emojis');
} else estilo.push('cálido, tuteando, sin emojis');
for (const v of Object.values(p.preferencias || {})) estilo.push(v);

const pedido = `Escribe el resumen de hoy (${dia.dia} ${dia.fecha}) para ${p.como_llamar || p.nombre || 'la persona'}.
Estilo: ${estilo.join(', ')}. Máximo 5 líneas, texto simple sin títulos ni asteriscos.
Empieza con un saludo corto, menciona lo más importante del día y termina con una sugerencia útil (por ejemplo, usar un espacio libre para un pendiente).

Actividades de hoy:
${eventos.join('\n') || '- Ninguna'}
Pendientes que vencen hoy:
${vencen.join('\n') || '- Ninguno'}
Otros pendientes:
${pendientes.join('\n') || '- Ninguno'}
Espacios libres: ${libres.join(', ') || 'ninguno'}
Lo que sabes de la persona: ${(d.recuerdos || []).join('; ') || 'poco todavía'}`;

const api = 'https://generativelanguage.googleapis.com/v1beta';
for (const modelo of d.modelos || []) {
  let r;
  try {
    r = await this.helpers.httpRequest({
      method: 'POST',
      url: `${api}/models/${modelo}:generateContent`,
      headers: { 'x-goog-api-key': d.clave, 'Content-Type': 'application/json' },
      body: { contents: [{ role: 'user', parts: [{ text: pedido }] }], generationConfig: { temperature: 0.8, maxOutputTokens: 4096 } },
      json: true, timeout: 60000, returnFullResponse: true, ignoreHttpStatusErrors: true,
    });
  } catch (err) { continue; }
  if (r.statusCode !== 200) continue;
  const partes = (((r.body.candidates || [])[0] || {}).content || {}).parts || [];
  const texto = partes.filter((x) => x.text && !x.thought).map((x) => x.text).join('').trim();
  if (texto) return [{ json: { nuevo: true, texto } }];
}
return [{ json: { nuevo: false, texto: null } }];
